def valider_mot_de_passe(mdp):
    contient_chiffre = any(caractere.isdigit() for caractere in mdp)
    return len(mdp) >= 8 and contient_chiffre and not (mdp == "password")

print(valider_mot_de_passe("abc123def"))
print(valider_mot_de_passe("password"))
print(valider_mot_de_passe("short1"))
